00074 // PSS data that is queued whilst base frames are decoded
00075 typedef struct {
00076     Packet packet;
00077     bool is_base_idr;
00078 } PssPacket;
00079 
00080 #define QUEUE_LIMIT 32
00081 
00082 static bool compare_packet_timestamps(const lctm::Packet &l, const lctm::Packet &r) {
00083     uint64_t lt = l.timestamp();
00084     uint64_t rt = r.timestamp();
00085     int64_t d = (rt - lt);
00086     return d < 0;
00087 }
00088 
00089 struct BufferCompare {
00090     bool operator()(const PssPacket &l, const PssPacket &r) { return compare_packet_timestamps(l.packet, r.packet); }
00091 };
00092 
00093 class BaseVideoDecoderJM : public BaseVideoDecoder {
00094 public:
00095     BaseVideoDecoderJM(BaseVideoDecoder::Output &output, Encapsulation encapsulation);
00096     ~BaseVideoDecoderJM() override;
00097 
00098     void start() override;
00099     void stop() override;
00100 
00101     void push_au(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr, int iPictureType) override;
00102 
00103     virtual void StatisticsComputation() override;
00104 
00105 private:
00106     void push_es(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr);
00107     void flush();
00108 
00109     void decode_enhanced_frames(DecodedPicList *pic_list, bool all_frames);
00110 
00111     // Consumer interface
00112     Output &output_;
00113 
00114     // Type of enhancement payload encapsulation
00115     Encapsulation encapsulation_;
00116 
00117     // Temp. buffer
00118     vector<uint8_t> buffer_;
00119 
00120     // Accumulated AUs for base
00121     vector<uint8_t> base_bitstream_;
00122 
00123     // Priority queues of buffers for base & pss ordered by timestamp
00124     priority_queue<PssPacket, vector<PssPacket>, BufferCompare> enhancement_queue_;
00125 
00126     //
00127     Codec* codec_ = nullptr;
00128     CodecContext context_ =0;
00129 };
