00137 void BaseVideoDecoderJM::start() {
00138     // Create base codec
00139     codec_ = CHECK(CodecCreate("avc", CodecOperation_Decode, ""));
00140 
00141     CodecError error=0;
00142     if(!codec_->create_context(&context_, "", &error)) {
00143         ERR("Codec error: %s", CodecErrorToString(codec_, error).c_str());
00144         error = 0;
00145     }
00146 }
00147 
00148 void BaseVideoDecoderJM::stop() {
00149     if(context_) {
00150         CHECK(codec_);
00151         codec_->release_context(context_);
00152         context_ = 0;
00153     }
00154 
00155     if(codec_) {
00156         CodecRelease(codec_);
00157         codec_ = 0;
00158     }
00159 }
00160 
00161 void BaseVideoDecoderJM::push_au(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr, int iPictureType) {
00162     if (data) {
00163         // Temp. copy of AU
00164         vector<uint8_t> b(data, data + data_size);
00165 
00166         // Pick out enhancement data - may be removed - new size is returned
00167         size_t new_size =
00168             scan_enhancement(b.data(), data_size, encapsulation_, BaseCoding_AVC, pts, [is_base_idr, this](const Packet &pkt) {
00169                 this->enhancement_queue_.push({pkt, is_base_idr});
00170             });
00171 
00172         b.resize(new_size);
00173 
00174         goReportStructure.miTimeStamp = (int)(pts);
00175         goReportStructure.miPictureType = iPictureType;
00176         goReportStructure.miBaseSize = (int)(new_size);
00177         goReportStructure.miEnhancementSize = (int)(data_size - new_size);
00178         goReportQueue.push(goReportStructure);
00179 
00180         // Flush any previous buffer
00181         if (!buffer_.empty()) {
00182             push_es(buffer_.data(), buffer_.size(), pts, is_base_idr);
00183         }
00184 
00185         buffer_.swap(b);
00186     } else {
00187         // this comment is specifically to trigger the pipeline (and for Florian) and serves no other purpose
00188         if (!buffer_.empty()) {
00189             push_es(buffer_.data(), buffer_.size(), pts, is_base_idr);
00190         }
00191 
00192         push_es(0, 0, pts, is_base_idr);
00193     }
00194 }
00195 
00196 void BaseVideoDecoderJM::push_es(const uint8_t *data, size_t data_size, uint64_t pts, bool is_base_idr) {
00197     CHECK(context_);
00198 
00199     // Push packet into codec
00200     CodecError error = 0;
00201     codec_->push_packet(context_, data, data_size, 0, data == nullptr, &error);
00202 
00203     // Pull images while codec continues to return them
00204     int32_t n = 0;
00205     int8_t eos = 0;
00206     do {
00207         CodecImage codec_image = {0};
00208         CodecError error = 0;
00209         n = codec_->pull_image(context_, &codec_image, 0, &eos, &error);
00210 
00211         if(n)  {
00212             // Get next PSS from queue
00213             //
00214             CHECK(!enhancement_queue_.empty());
00215             PssPacket pss = enhancement_queue_.top();
00216             enhancement_queue_.pop();
00217 
00218             // Send to enhancement decoder
00219             //
00220             PacketView enhancement_view(pss.packet);
00221             output_.push_base_enhancement(&codec_image, enhancement_view.data(), enhancement_view.size(), pss.packet.timestamp(),
00222                                           pss.is_base_idr);
00223         }
00224     } while(n);
00225 }
00226 
00227 void BaseVideoDecoderJM::flush() {
00228 
00229     // Poke bitstream into our JM hooks
00230     inject_annex_b_bitstream(base_bitstream_.data(), (unsigned)base_bitstream_.size());
00231 
00232     InputParameters input_parameters;
00233     memset(&input_parameters, 0, sizeof(input_parameters));
00234     strcpy(input_parameters.infile, "");
00235     strcpy(input_parameters.outfile, "");
00236     strcpy(input_parameters.reffile, "");
00237 
00238     const char *const decoder_args[] = {"ldecod"};
00239     ParseCommand(&input_parameters, ARRAY_SIZE(decoder_args), (char **)decoder_args);
00240 
00241     // Open decoder
00242     if (OpenDecoder(&input_parameters) != DEC_OPEN_NOERR) {
00243         ERR("Cannot open base decoder");
00244     }
00245 
00246     p_Dec->p_Vid->p_out = -2;
00247 
00248     // Run decoder
00249     //
00250     DecodedPicList *pDecPicList = 0;
00251     int frame_count = 0;
00252 
00253     int r = 0;
00254     do {
00255         r = DecodeOneFrame(&pDecPicList);
00256 
00257         if (r == DEC_EOS || r == DEC_SUCCEED) {
00258             decode_enhanced_frames(pDecPicList, false);
00259             frame_count++;
00260         } else {
00261             ERR("Error in decoding process: 0x%x", r);
00262         }
00263     } while ((r == DEC_SUCCEED) && ((p_Dec->p_Inp->iDecFrmNum == 0) || (frame_count < p_Dec->p_Inp->iDecFrmNum)));
00264 
00265     FinitDecoder(&pDecPicList);
00266 
00267     // Write last frame
00268     decode_enhanced_frames(pDecPicList, true);
00269 
00270     CloseDecoder();
00271 }
00272 
00273 void BaseVideoDecoderJM::decode_enhanced_frames(DecodedPicList *pic, bool all_frames) {
00274     // Check picture and plane pointers - valid flag seems to be wrong sometimes!?
00275     if (!pic || !pic->pY || !pic->pU || !pic->pV) {
00276         return;
00277     }
00278 
00279     if (!pic->bValid) {
00280         INFO("Picture not marked valid?");
00281     }
00282 
00283     do {
00284         BasePicture base_picture = {0};
00285         base_picture.bpp = ((pic->iBitDepth + 7) >> 3);
00286         base_picture.width_y = pic->iWidth;
00287         base_picture.height_y = pic->iHeight;
00288         base_picture.stride_y = pic->iYBufStride;
00289 
00290         base_picture.width_uv = (pic->iYUVFormat != YUV444) ? (pic->iWidth / 2) : pic->iWidth;
00291         base_picture.height_uv = (pic->iYUVFormat == YUV420) ? (pic->iHeight / 2) : pic->iHeight;
00292         base_picture.stride_uv = pic->iUVBufStride;
00293 
00294         base_picture.data_y = pic->pY;
00295         base_picture.data_u = pic->pU;
00296         base_picture.data_v = pic->pV;
00297 
00298         // Get next PSS from queue
00299         //
00300         CHECK(!enhancement_queue_.empty());
00301         PssPacket pss = enhancement_queue_.top();
00302         enhancement_queue_.pop();
00303 
00304         // Send to enhancement decoder
00305         //
00306         PacketView enhancement_view(pss.packet);
00307         output_.push_base_enhancement(&base_picture, enhancement_view.data(), enhancement_view.size(), pss.packet.timestamp(),
00308                                       pss.is_base_idr);
00309 
00310         // Mark as used and move to next
00311         pic->bValid = 0;
00312         pic = pic->pNext;
00313     } while (pic != NULL && pic->bValid && all_frames);
00314 }
